-- ----------------------------
-- View structure for v_orderfreight
-- ----------------------------
DROP VIEW IF EXISTS `v_orderfreight`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_orderfreight` AS select `orderDetail`.`ordersNo` AS `ordersNo`,sum(`orderDetail`.`landFreight`) AS `landFreight`,sum(`orderDetail`.`seaFreight`) AS `seaFreight`,sum(`orderDetail`.`freight`) AS `freight` from `orderDetail` where ((`orderDetail`.`cancelFlag` = 0) and (`orderDetail`.`isAdjusted` = 0)) group by `orderDetail`.`ordersNo`;

SET FOREIGN_KEY_CHECKS = 1;
